const LAW = { pts: [[10,6],[25,36],[50,168],[100,600],[200,1680],[300,3120],[500,6720],[750,13440],[1000,23520]], m: 1.326, from: 10 };
const lawH = (L) => { const p = LAW.pts; let i = 1; while (i < p.length - 1 && p[i][0] < L) i++; const [a, ha] = p[i - 1], [b, hb] = p[i]; return Math.exp(Math.log(ha) + (Math.log(hb) - Math.log(ha)) * (Math.log(L) - Math.log(a)) / (Math.log(b) - Math.log(a))); };
const LAW_XP = [];
const lawXp = (L) => { if (!LAW_XP.length) LAW_XP[LAW.from] = xpForLevelOn(LEVEL_ROWS, LAW.from); for (let l = LAW_XP.length; l <= L; l++) LAW_XP[l] = LAW_XP[l - 1] + Math.max(1, Math.round((lawH(l) - lawH(l - 1)) * LEVEL_PACE.contract.a * (l - 1) ** LEVEL_PACE.contract.b * LAW.m)); return LAW_XP[L]; };
export function charXpForLevel(lv) { const L = Math.max(1, Math.floor(Number(lv) || 1)); return L <= LAW.from ? xpForLevelOn(LEVEL_ROWS, L) : lawXp(L); }
